export const spa1Tasks={"system": [{"id": "compare", "title": "Compare and explain", "kind": "system", "type": "compare", "cases": [["0", "Our solar system is part of…", ["The Milky Way galaxy", "Every galaxy simultaneously", "Only Earth’s atmosphere"], 0, "A galaxy contains many stars and systems."], ["1", "A nebula contracts mainly because of…", ["Only electron colour", "Gravitational attraction", "Sound in vacuum"], 1, "Gravity draws matter together."], ["2", "Main-sequence stability involves…", ["No gravity", "No energy release", "A balance of gravitational collapse and outward effects from fusion energy"], 2, "Fusion maintains the energy supply."]]}, {"id": "calculate", "type": "sequence", "title": "Build the explanation in order", "kind": "system", "route": ["cloud", "collapse", "hot", "fusion"], "labels": ["Begin with a gas/dust nebula", "Gravity contracts the cloud", "Protostar temperature and pressure rise", "Fusion begins and main-sequence balance develops"], "why": "Follow the causal or measurement sequence in Discover."}, {"id": "model", "title": "Predict and compare every setting", "kind": "system-model", "type": "experiment", "experiment": "system", "why": "Use the selected quantities and the stated physical assumptions."}], "stars": [{"id": "compare", "title": "Compare and explain", "kind": "stars", "type": "compare", "cases": [["0", "The main determinant of a star’s life pathway is its…", ["Initial mass", "Screen colour", "Distance from Earth alone"], 0, "Mass controls the conditions and evolution."], ["1", "A Sun-like star leaves a…", ["Mandatory black hole", "White dwarf after red-giant stages", "Neutron star after every case"], 1, "The high-mass pathway is different."], ["2", "A supernova helps distribute…", ["Only original hydrogen", "Only photons with no matter", "Elements into surrounding space"], 2, "This enriches material for later systems."]]}, {"id": "calculate", "type": "sequence", "title": "Build the explanation in order", "kind": "stars", "route": ["main", "giant", "shed", "white"], "labels": ["Sun-like main sequence", "Expand into a red giant", "Shed outer material", "Leave a white dwarf that cools"], "why": "Follow the causal or measurement sequence in Discover."}, {"id": "model", "title": "Predict and compare every setting", "kind": "stars-model", "type": "experiment", "experiment": "stars", "why": "Use the selected quantities and the stated physical assumptions."}], "orbits": [{"id": "compare", "title": "Compare and explain", "kind": "orbits", "type": "compare", "cases": [["0", "The force maintaining a circular orbit is…", ["Gravity toward the centre", "An outward magnetic force necessarily", "No force"], 0, "Gravity changes the velocity direction."], ["1", "A human-made orbiting object is…", ["A natural moon", "An artificial satellite", "A star necessarily"], 1, "Distinguish origin from gravitational mechanism."], ["2", "An orbiting satellite’s instantaneous velocity is…", ["Toward the centre always", "Zero", "Tangent to the path"], 2, "It is not the same direction as the inward force."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "orbits-data", "type": "numeric", "prompt": "A toy circular path has circumference120 units and period30 s. Find average path speed.", "answer": 4, "unit": "stated units", "reasonChoices": ["120 ÷ 30", "Multiply all supplied quantities regardless of relationship", "Ignore the stated conditions"], "reason": 0, "why": "Use the relationship, direction and units in Discover."}, {"id": "model", "title": "Predict and compare every setting", "kind": "orbits-model", "type": "experiment", "experiment": "orbits", "why": "Use the selected quantities and the stated physical assumptions."}, {"id": "higher", "title": "Higher: explain the extension", "kind": "orbits", "type": "compare", "higher": true, "cases": [["0", "For stable circular orbits around the same body, a change in orbital speed requires…", ["A change in orbital radius", "Gravity to disappear", "A constant radius always"], 0, "Different stable orbital speeds correspond to different radii."]]}], "redshift": [{"id": "compare", "title": "Compare and explain", "kind": "redshift", "type": "compare", "cases": [["0", "Redshift means an observed shift toward…", ["Longer wavelengths", "Shorter wavelengths", "No spectral pattern"], 0, "Compare matching features with a reference."], ["1", "The distance/redshift pattern supports…", ["A static universe with no change", "Expansion of space", "Earth as a special universal centre"], 1, "The pattern is seen from our viewpoint without a special centre here."], ["2", "The Big Bang model describes an early state that was…", ["Cold and dilute", "A chemical fire in air", "Extremely hot and dense"], 2, "It is a cosmological model supported by observations."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "redshift-data", "type": "numeric", "prompt": "A500 nm reference line is observed at560 nm. Find the wavelength increase in nm.", "answer": 60, "unit": "stated units", "reasonChoices": ["560 − 500", "Multiply all supplied quantities regardless of relationship", "Ignore the stated conditions"], "reason": 0, "why": "Use the relationship, direction and units in Discover."}, {"id": "model", "title": "Predict and compare every setting", "kind": "redshift-model", "type": "experiment", "experiment": "redshift", "why": "Use the selected quantities and the stated physical assumptions."}]};
export const experimentOptions={"system": {"a": [["planet", "Planet"], ["moon", "Natural moon"]], "b": [["star", "Orbiting its star"], ["planet", "Orbiting its planet"]], "labels": ["Object", "Orbit centre"], "unit": "stated natural relationship", "choices": [["yes", "Matches the stated relationship"], ["no", "Does not match this relationship"]]}, "stars": {"a": [["sun", "Sun-like mass"], ["massive", "Much higher mass"]], "b": [["white", "White-dwarf remnant"], ["neutron", "Neutron-star/black-hole pathway"]], "labels": ["Initial mass group", "Endpoint candidate"], "unit": "pathway match", "choices": [["yes", "Matches the pathway"], ["no", "Does not match the pathway"]]}, "orbits": {"a": [["right", "Satellite right of centre"], ["top", "Satellite above centre"]], "b": [["planet", "Planet-centred orbit"], ["star", "Star-centred orbit"]], "labels": ["Orbital position", "Central attracting body"], "unit": "gravity direction", "choices": [["left", "Leftward toward centre"], ["down", "Downward toward centre"]]}, "redshift": {"a": [["400", "400 nm reference"], ["600", "600 nm reference"]], "b": [["20", "20 nm increase"], ["40", "40 nm increase"]], "labels": ["Reference wavelength", "Observed shift"], "unit": "nm observed wavelength"}};
export const tasksForSpa1=(k,tier="Higher")=>spa1Tasks[k].filter(t=>!t.higher||tier==="Higher");
export const validSpa1=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const numericSpa1=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;export const advanceSpa1=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;

export function experimentResult(k,a,b){const o=experimentOptions[k];if(!o||!o.a.some(x=>x[0]===String(a))||!o.b.some(x=>x[0]===String(b)))throw new RangeError('Choose stated settings.');const x=Number(a),y=Number(b);let value;
if(k==='system')value=(a==='planet'&&b==='star')||(a==='moon'&&b==='planet')?'yes':'no';
if(k==='stars')value=(a==='sun'&&b==='white')||(a==='massive'&&b==='neutron')?'yes':'no';
if(k==='orbits')value=a==='right'?'left':'down';
if(k==='redshift')value=x+y;
return{value,a,b};}

export const predictionValid=(k,v,r)=>experimentOptions[k].choices?String(v)===String(r.value):numericSpa1(v,r.value);
export const outputLabel=(k,v)=>experimentOptions[k].choices?.find(x=>String(x[0])===String(v))?.[1]??Number(Number(v).toFixed(3))+' '+experimentOptions[k].unit;
export const experimentCases=k=>experimentOptions[k].a.flatMap(([a])=>experimentOptions[k].b.map(([b])=>a+':'+b));export const experimentValid=(k,v)=>experimentCases(k).every(x=>v.observed?.includes(x))&&v.interpretation==='limited';
